{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Duvelisib, a chiral kinase inhibitor with an aminopurine-like heteroaryl and chlorinated fused aromatic system, has an absolute oral bioavailability of 42% in humans, supporting F >= 20% for the similarly structured query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Idelalisib, a structurally related chiral kinase inhibitor, has an oral bioavailability of 34% in humans, above the 20% threshold and supportive for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Vorasidenib, which shares CF3 and aminopyrimidine motifs with the query, has a mean absolute oral bioavailability of 34% in humans, supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Erlotinib, a 4-anilinoquinazoline kinase inhibitor, has an absolute oral bioavailability of 76% in cancer patients, demonstrating that this inhibitor class is generally orally bioavailable well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Lapatinib, despite being described as having low bioavailability in qualitative terms, was estimated at 30% oral bioavailability in a Phase I study, which is still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Selatinib, a close anilinoquinazoline analogue, showed high oral bioavailability in healthy subjects, supporting a high prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Afatinib, an orally administered anilinoquinazoline kinase inhibitor, showed good oral bioavailability in Phase I human studies, supporting the likelihood of adequate oral absorption for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved quantitative human bioavailability values for structurally related kinase inhibitors are at or above 30%, and qualitative reports for close analogues indicate good oral bioavailability. No affirmative evidence supports F < 20%, so the query is predicted to have high oral bioavailability at the 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule.",
    "Morgan similarities to the evidence molecules are modest (0.16-0.26), limiting direct structural transferability.",
    "The query contains a pyridine N-oxide and multiple aromatic/CF3 groups whose effects on solubility, permeability, and first-pass metabolism are not directly captured by the retrieved analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

